import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
def S(doc,name,F,v='image'): save(doc,name,F,'a',verified=v)

S('0198',"رسوم خدمات طلبة البرنامج الموازي لغير الأردنيين",[
("number",[1],"الجدول","رسوم الخدمات لطلبة البرنامج الموازي من غير الأردنيين للفصل الواحد 116 دولاراً، موزعة كالتالي: التأمين على الحياة 5 دولارات، والتأمين الطبي 26 دولاراً، والمطبوعات والنشرات 25 دولاراً، والهوية الجامعية 5 دولارات، والنشاط الطلابي 25 دولاراً، وصندوق البريد 5 دولارات، والمكتبة 25 دولاراً.",
 "كم رسوم الخدمات للفصل الواحد لطلبة البرنامج الموازي من غير الأردنيين؟","كم رسم التأمين الطبي لطالب غير أردني في البرنامج الموازي؟","قديش رسوم الخدمات للطالب غير الأردني بالموازي؟"),
("number",[1],"الجدول","على طلبة البرنامج الموازي من غير الأردنيين دفع: تأمينات ورسوم 100 دولار (30 دولاراً تأمين مسترد و70 دولاراً رسوم قبول)، وامتحان مستوى اللغة الإنجليزية 10 دولارات، وامتحان مستوى مهارات الحاسوب 15 دولاراً، وخدمات تكنولوجية 116 دولاراً، وطلب التحاق 50 دولاراً. ويستثنى الطلبة المقيمون في الضفة الغربية وقطاع غزة (ومصدر الشهادة من مكان الإقامة).",
 "كم رسم طلب الالتحاق لغير الأردني في البرنامج الموازي؟","كم يبلغ التأمين المسترد ورسم القبول لغير الأردنيين؟","شو الرسوم اللي على غير الأردني عند القبول بالموازي؟"),
])

S('0202',"رسوم الساعات المعتمدة لأبناء الهيئات التدريسية والعاملين في الجامعات الأردنية",[
("number",[1],"البرنامج العادي","تحدد نسبة رسوم الساعات المعتمدة لأبناء أعضاء الهيئات التدريسية والعاملين في الجامعات الأردنية الرسمية بنسبة (50%) من الرسوم المقررة في البرنامج العادي، إذا استوفوا الشروط، ومنها أن يكون والد/والدة الطالب على رأس عمله في إحدى الجامعات الأردنية الرسمية أو في جامعة البلقاء التطبيقية أو قد أمضى في خدمة الجامعة عشر سنوات على الأقل، وألا يكون الطالب مبعوثاً من جهة رسمية أو غير رسمية، وأن يكون في مرحلة البكالوريوس.",
 "كم تبلغ نسبة خصم رسوم الساعات لأبناء العاملين في الجامعات الرسمية في البرنامج العادي؟","ما شروط حصول ابن العامل على خصم الرسوم في البرنامج العادي؟","شو الشروط عشان ابن الموظف ياخد خصم 50% على الساعات؟"),
("number",[1],"البرنامج العادي","إذا حصل الطالب ابن العامل على معدل فصلي (سنوي) جيد فما فوق فتخصم رسوم الساعات المعتمدة له بنسبة (10%) من الرسوم المقررة في الفصل (السنة) الذي يلي الفصل (السنة) الذي حصل فيه على تقدير جيد فما فوق. وفي حال التحويل إلى تخصص آخر في تخصصات نظام الساعات يستوفى من الطالب (10%) من الرسوم في حال كان معدله الفصلي الأخير في التخصص السابق جيد.",
 "كم الخصم الإضافي لابن العامل الحاصل على معدل جيد فما فوق؟","ماذا يحدث لرسوم ابن العامل إذا حول إلى تخصص آخر في نظام الساعات؟","اذا ابن الموظف جاب جيد بنزل عليه رسوم؟"),
("number",[1],"البرنامج الموازي","تحدد رسوم الساعات المعتمدة لأبناء العاملين في جامعة العلوم والتكنولوجيا الأردنية للبرنامج الدراسي الموازي بـ (50%) من الرسوم الجامعية المقررة في البرنامج الموازي، ولا يجوز تخفيض هذه النسبة لأي سبب، على ألا تزيد نسبة المقبولين عن (5%) من أعداد الطلبة المقبولين تنافسياً في البرنامج الموازي. وتحدد رسوم أبناء العاملين في جامعة اليرموك في البرنامج الموازي بـ (50%) على ألا تزيد نسبة المقبولين عن (3%).",
 "كم نسبة رسوم ابن العامل في الجامعة بالبرنامج الموازي؟","ما الحد الأعلى لنسبة المقبولين من أبناء العاملين في البرنامج الموازي؟","قديش بدفع إذا بنت موظف بالجامعة وقدمت موازي؟"),
])

S('0203',"رسوم الساعات المعتمدة لأبناء الهيئات التدريسية والعاملين في الجامعات الأردنية للبرنامج الموازي",[
("rule",[1],"قرار 2011/7، البند 1","قبول أبناء العاملين في جامعة العلوم والتكنولوجيا الأردنية في البرنامج الدراسي الموازي في الجامعة اعتباراً من بدء العام الجامعي 2005/2006 شريطة أن يكون والد الطالب على رأس عمله في الجامعة أثناء قبول الطالب أو أن يكون قد أمضى في خدمة الجامعة عشر سنوات على الأقل أو أن يكون قد توفي وهو على رأس عمله، وألا يكون الطالب مبعوثاً من جهة رسمية أو غير رسمية، وأن يكون في مرحلة البكالوريوس، وأن يكون حاصلاً على الثانوية العامة الأردنية للعام الذي تقدم به للقبول.",
 "ما شروط قبول أبناء العاملين في الجامعة بالبرنامج الموازي بنصف الرسوم؟","هل يشترط أن يحمل ابن العامل الثانوية العامة الأردنية للحصول على خصم الموازي؟","شو شروط خصم أبناء العاملين بالموازي؟"),
("number",[1],"قرار 2006، البند 1 و2","يقبل أبناء العاملين في جامعة اليرموك في البرنامج الموازي في جامعة العلوم والتكنولوجيا الأردنية بشرط ألا يكون التخصص المتقدم له الطالب موجوداً في جامعة اليرموك، وتحدد رسوم الساعات المعتمدة بـ (50%) من الرسوم الجامعية المقررة في البرنامج الموازي، على ألا تزيد نسبة المقبولين عن (3%) من أعداد الطلبة المقبولين تنافسياً في البرنامج الموازي.",
 "هل يقبل أبناء العاملين في جامعة اليرموك بالموازي بخصم؟","ما الحد الأقصى لنسبة المقبولين من أبناء العاملين في جامعة اليرموك؟","ابن موظف يرموك بقدر ياخد خصم عنا؟"),
])

S('0204',"رسوم الساعات المعتمدة لأبناء العشائر في البادية الأردنية والمدارس ذات الظروف الخاصة",[
("rule",[1],"البند 1 و2","طلبة العام الدراسي 2003/2004 المشمولون في المكرمة الملكية السامية لأبناء العشائر في البادية الأردنية والمدارس ذات الظروف الخاصة تم إعفاؤهم من الزيادة المقررة على الرسوم ومعاملتهم حسب الرسوم القديمة (2002/2003)، وعند البدء بتغيير التخصص يتم استيفاء الرسوم منهم في التخصص الجديد حسب سنة قبول الطالب في الجامعة في المرة الأولى بغض النظر عن أن الطالب كان قد أعفي من الزيادة.",
 "ما معاملة رسوم طلبة المكرمة الملكية لأبناء العشائر في البادية الأردنية؟","ماذا يحدث لرسوم طالب المكرمة الملكية عند تغيير تخصصه؟","شو بصير برسومي اذا كنت من أبناء العشائر بالمكرمة وغيرت تخصصي؟"),
])

S('0205',"قرارات مالية متفرقة / الرسوم الدراسية / الديوان الملكي",[
("rule",[1],"قرار مجلس الأمناء 1999/9/19","الطلبة المقبولون عن طريق الديوان الملكي في البرنامج الموازي يتحملون رسوم الساعات المعتمدة للمساقات التالية (أسوة بطلبة البرنامج العادي): الساعات التي يرسب فيها أو يحرم منها بسبب الغياب، والساعات التي يتم إسقاطها (خلال فترة السحب)، والساعات التي يسجلها ثم يؤجل الفصل الدراسي، والساعات للمساقات التي يدرسها للمرة الثانية (إذا كانوا نجحوا بها)، والمساقات الزائدة عن الخطة، ويطالب بها مالياً في بداية الفصل اللاحق.",
 "أي الساعات يتحمل رسومها طلبة الديوان الملكي في البرنامج الموازي؟","هل يدفع طالب الديوان الملكي رسوم الساعات التي يرسب فيها؟","شو الساعات اللي لازم يدفع رسومها طالب الديوان الملكي؟"),
("rule",[1],"قرار مجلس الأمناء 2005","منح الطلبة المقبولين للعام الدراسي 2005/2004 عن طريق الديوان الملكي إعفاء من رسوم الساعات المعتمدة وأي رسوم أخرى. وبعد ذلك يتحمل الطلبة المقبولون عن طريق الديوان الملكي في البرنامج الموازي رسوم الخدمات الفصلية التي تتحملها طلبة الدراسة الموازي، ورسوم الساعات المعتمدة التي يرسب فيها الطالب.",
 "هل يتحمل طلبة الديوان الملكي رسوم الخدمات الفصلية؟","ماذا تشمل الرسوم التي يتحملها طلبة الديوان الملكي في الموازي؟","طالب الديوان الملكي بدفع رسوم خدمات؟"),
("rule",[1],"قرار مجلس الأمناء، الطلبة المبعوثون","يتم اعتماد رسوم الساعات الجامعية لكافة الطلبة المبعوثين فقط على نفقة مكتب جلالة الملكة رانيا المعظمة، ويتحمل الطالب المبعوث رسوم التسجيل وأي رسوم أخرى مترتبة عليه ما عدا رسوم الساعات الجامعية، ويتحمل الطالب الذي يرسب في مادة ثمن إعادة المادة بالكامل.",
 "من يتحمل رسوم الساعات الجامعية للطلبة المبعوثين على نفقة مكتب جلالة الملكة رانيا؟","هل يتحمل الطالب المبعوث رسوم التسجيل؟","اذا رسبت بمادة وأنا مبعوث، مين بدفع رسوم الإعادة؟"),
("rule",[1],"قرار آخر","طلبة الديوان الملكي / البرنامج الموازي الذين يفصلون من التخصص ويتم إعطاؤهم فصل إضافي بالبرنامج الموازي يكون هذا الفصل على حساب الديوان الملكي كما كانوا عند بداية قبولهم. وإذا لم يتمكنوا من رفع معدلهم يتم فصلهم حسب التعليمات، وإذا رغب في تغيير التخصص يكون ذلك في البرنامج الموازي وعلى حسابه الخاص.",
 "على حساب من يكون الفصل الإضافي لطالب الديوان الملكي المفصول من التخصص؟","هل يستطيع طالب الديوان الملكي تغيير تخصصه على حساب الديوان؟","اذا انفصلت من تخصصي وأنا طالب ديوان ملكي، مين بدفع الفصل الإضافي؟"),
])

S('0206',"قرارات مالية متفرقة / الرسوم الدراسية لطلبة البكالوريوس",[
("number",[1],"قرار مجلس العمداء 2006","يجب التأكد من استيفاء مبلغ (5) دنانير رسم طلب التحاق للطلبة الذين قبلوا في البرنامج العادي وليس عن طريق قائمة القبول الموحد (كأبناء العاملين، والتفوق الفني، والتفوق الرياضي، والديوان الملكي).",
 "كم رسم طلب الالتحاق للمقبولين في البرنامج العادي من خارج قائمة القبول الموحد؟","من يدفع رسم طلب التحاق 5 دنانير في البرنامج العادي؟","قديش رسم طلب الالتحاق اذا انقبلت كابن موظف؟"),
("rule",[1],"قرار مجلس العمداء","يفوض مجلس العمداء رئيس الجامعة البت في موضوع ترصيد الرسوم الجامعية للطلبة الذين ينسحبون من الفصل الدراسي لظروف قاهرة.",
 "من يبت في ترصيد الرسوم للطلبة المنسحبين من الفصل لظروف قاهرة؟","هل ترصد الرسوم للطالب المنسحب لظروف قاهرة؟","مين بقرر ترصيد رسومي اذا انسحبت من الفصل لظرف قاهر؟"),
("rule",[1],"قرار 2003","لا يخول قانون الجامعات الأردنية الرسمية مجلس أمناء الجامعة صلاحية إعفاء أي من الطلبة من الرسوم الجامعية.",
 "هل يملك مجلس الأمناء صلاحية إعفاء الطلبة من الرسوم الجامعية؟","من يملك صلاحية الإعفاء من الرسوم الجامعية حسب قانون الجامعات الرسمية؟","بقدر مجلس الأمناء يعفيني من الرسوم؟"),
("rule",[1],"قرار 2004","في حال انتقال الطالب المستجد من جامعة رسمية إلى جامعة رسمية أخرى تعاد الرسوم للطالب عن طريق التحويل المباشر إلى الجامعة التي انتقل إليها حسب الأصول، ويستثنى من ذلك الطلبة المقبولون عن طريق البرامج الأخرى (المسائي والموازي والدولي والاستكمالي).",
 "ماذا يحدث للرسوم إذا انتقل الطالب المستجد من جامعة رسمية إلى أخرى؟","هل تعاد الرسوم لطلبة البرنامج الموازي عند الانتقال بين الجامعات الرسمية؟","اذا انتقلت من جامعة رسمية لجامعة رسمية ثانية بترجعلي الرسوم؟"),
("rule",[1],"قرار 2004","يتحمل الطالب في الجامعة رسوم التدريب بغض النظر سواء كان داخل أو خارج الجامعة (إن كانت الجامعة تستوفي رسوماً عن هذا التدريب) وأن تقترن موافقة العميد على التدريب بشرط دفع الرسوم الجامعية المقررة قبل البدء في التدريب.",
 "من يتحمل رسوم التدريب الميداني؟","هل يشترط دفع الرسوم الجامعية للموافقة على التدريب؟","لازم أدفع رسوم قبل ما أبدأ التدريب؟"),
("rule",[1],"قرار مجلس الأمناء 2000/5 (الموازي)","لا تحول الرسوم الجامعية المدفوعة من الطالب المقبول في البرنامج الدراسي الموازي في الجامعة إذا تم قبوله في البرنامج العادي أو الموازي أو الدولي في جامعة أردنية رسمية أخرى. ويتم ترصيد رسوم طالب البرنامج الموازي إذا تم قبوله في البرنامج العادي للاستفادة منها في فصول لاحقة، وتجري تسوية مالية لرسوم طالب البرنامج العادي إذا تم قبوله في البرنامج الموازي بحيث يراعى المبلغ المدفوع بالبرنامج العادي.",
 "ماذا يحدث لرسوم طالب الموازي إذا قبل لاحقاً في البرنامج العادي؟","هل تحول رسوم الطالب المقبول في الموازي إذا قبل في جامعة رسمية أخرى؟","اذا انقبلت بالعادي بعد ما دفعت رسوم الموازي شو بصير بالفلوس؟"),
("rule",[1],"قرار (الطلبة الأردنيون العائدون من العراق)","يكون قبول الطلبة الأردنيين العائدين من العراق في الجامعات الرسمية على أساس الرسوم الدراسية للبرنامج العادي المطبقة في الجامعة على اعتبار أنهم طلبة مسجلون منذ الفصل الدراسي الثاني للعام الجامعي 2003/2002، كما يعفى الطلبة من رسوم التسجيل التي تتقاضاها الجامعات الأردنية من الطلبة المستجدين وكذلك رسوم طلبات الالتحاق.",
 "ما الرسوم التي تطبق على الطلبة الأردنيين العائدين من العراق؟","هل يعفى الأردنيون العائدون من العراق من رسوم التسجيل ورسوم طلب الالتحاق؟","ابن راجع من العراق، كم رسومه؟"),
("number",[1],"قرار","وافق مجلس الأمناء على إرجاع المبالغ الزائدة عن الرسوم الجامعية للطالب المنتظم والمسجل الحد الأدنى من الساعات (12) ساعة على الأقل من الرسوم التي دفعها الطالب زيادة عن الرسوم الجامعية والتي بقيت أمانات له للفصل التالي.",
 "هل تعاد المبالغ الزائدة المدفوعة عن الرسوم الجامعية للطالب؟","كم الحد الأدنى من الساعات المسجلة ليسترد الطالب المبالغ الزائدة؟","دفعت أكثر من الرسوم وبقي رصيد، برجعولي إياه؟"),
],)

S('0207',"قرارات مالية متفرقة / الطلبة الوافدين",[
("number",[1],"القرار 1","الرسوم الدراسية (رسوم الساعات) للطالب الأردني للطلبة السعوديين المقبولين على حساب وزارة التعليم العالي السعودية اعتباراً من العام الدراسي 2004/2005 أقل بـ (15%) من رسوم الطالب الأردني.",
 "كم تقل رسوم الطلبة السعوديين المقبولين على حساب وزارة التعليم العالي السعودية عن رسوم الطالب الأردني؟","ما نسبة تخفيض الرسوم للطلبة السعوديين المبتعثين من وزارة التعليم العالي السعودية؟","الطالب السعودي بدفع أقل من الأردني قديش؟"),
("rule",[1],"القرار 2","يعامل الطلبة الوافدون في البرنامج العادي (غير الأردنيين، المستجدين) الدارسين في الجامعات الأردنية لدرجة البكالوريوس معاملة الطلبة الأردنيين من حيث استيفاء الرسوم (رسومهم حسب البرنامج العادي مضافاً له رسم طلب الالتحاق)، وهم: أبناء الدول العربية التي تعامل الأردنيين في جامعاتها معاملة أبنائها وفق التبادل الثقافي، وأبناء المسلمين من غير الدول العربية الذين يدرسون الشريعة الإسلامية أو اللغة العربية، وأبناء فلسطين المقبولون وفق البرنامج التنفيذي، وأبناء الأردنيات المتزوجات من غير الأردنيين اللواتي يحملن دفتر عائلة أردنياً، والموفدون على نفقة وزارة التعليم العالي والبحث العلمي، والطلبة المبعوثون من جهات اعتبارية كأبناء عرب 48.",
 "أي فئات الطلبة الوافدين تعامل معاملة الأردنيين في الرسوم؟","هل يعامل ابن الأردنية المتزوجة من غير أردني معاملة الأردني في الرسوم؟","مين من الطلبة الوافدين بدفع نفس رسوم الأردنيين؟"),
("rule",[1],"قرار مجلس الأمناء 2012/10/4","ألغى مجلس الأمناء قراره رقم (2012/65) الخاص بعدم الموافقة على معاملة أبناء الأردنيات المتزوجات من غير الأردنيين من حيث الرسوم، ووافق على معاملة الطلبة غير الأردنيين من أبناء الأردنيات المتزوجات من غير الأردنيين اللواتي يحملن دفتر عائلة أردني معاملة الطلبة الأردنيين في مرحلة البكالوريوس من حيث الرسوم الجامعية، وعدم معاملتهم معاملة الأردنيين في مرحلة الماجستير.",
 "هل يعامل ابن الأردنية في مرحلة الماجستير معاملة الأردنيين من حيث الرسوم؟","كيف يعامل أبناء الأردنيات المتزوجات من غير الأردنيين في الرسوم؟","ابن الأردنية معاملته بالماجستير مثل الأردني؟"),
("rule",[1],"ملاحظات القبول","الشهادات الأجنبية يحسب المعدل حسب أسس القبول في الجامعة، ويجب أن تكون مصدقة من وزارة التربية والتعليم الأردنية، وأي طالب مبعوث يجب عليه إحضار كتاب تغطية مالية من الجهة الباعثة، كما يجب التأكد من فرع الشهادة وخاصة شهادة البجروت، وأن الشهادة الإسرائيلية هي شهادة البجروت وليس الشهادة المدرسية.",
 "ما الوثيقة المطلوبة من الطالب الوافد المبعوث؟","هل يلزم تصديق الشهادات الأجنبية من وزارة التربية والتعليم الأردنية للطلبة الوافدين؟","شو بدي اذا أنا وافد ومبعوث؟"),
])

S('0208',"قرارات مالية متفرقة / الموازي",[
("number",[1],"قرار 2001","يرد ما نسبته (50%) من الرسوم الجامعية المدفوعة من طالب البرنامج الدراسي الموازي المستجد في حالة انسحابه من الجامعة خلال الأسبوع الأول من بدء الدراسة في الفصل الذي قبل فيه، ويطبق هذا القرار على طلبة البرنامج الموازي المقبولين اعتباراً من بدء الفصل الأول من العام الجامعي 2002/2001.",
 "كم نسبة الرسوم التي ترد لطالب الموازي المستجد إذا انسحب في الأسبوع الأول؟","هل ترد رسوم الموازي للمستجد المنسحب من الجامعة؟","اذا انسحبت بالأسبوع الأول من الموازي برجعولي كم؟"),
("rule",[1],"قرار","الموافقة على ترصيد فرق الرسوم ما بين رسم المساق في البرنامج الدراسي الموازي ورسم المساق في البرنامج العادي، لطالب البرنامج الدراسي الموازي الذي يسجل لمساق ثم يتم سحبه من قبل وحدة القبول والتسجيل لعدم تحقيق شرط المتطلب السابق أو المرافق وذلك خلال فترة أربعة أسابيع من بدء الفصل الدراسي المحددة في التقويم الجامعي.",
 "ماذا يحدث لفرق الرسوم إذا سحبت وحدة القبول المساق من طالب الموازي لعدم تحقيق المتطلب؟","خلال كم أسبوع من بداية الفصل يتم سحب المساق وترصيد فرق الرسوم لطالب الموازي؟","اذا انسحب مني مساق بسبب المتطلب بالموازي برجعولي الفلوس؟"),
("number",[1],"قرار مجلس الأمناء بالتمرير 2013","ترد الساعات المدفوعة من طالب البرنامج الدراسي الموازي المستجد في حال انسحابه من الجامعة وفقاً للتقويم الجامعي المعتمد وحسب النسب التالية: (90%) إذا انسحب رسمياً من الجامعة قبل بدء الفصل الدراسي، و(75%) إذا انسحب في الأسبوع الأول من بدء الفصل أو خلال الأسبوع الأول من قبوله، و(50%) في الأسبوع الثاني أو خلال الأسبوع الأول من قبوله، و(25%) في الأسبوع الثالث. ولا يرد للطالب أي نسبة من الرسوم بعد الأسبوع الثالث.",
 "ما نسب إرجاع الرسوم لطالب الموازي المستجد حسب موعد الانسحاب؟","كم تبلغ نسبة الرسوم المسترجعة إذا انسحب طالب الموازي المستجد في الأسبوع الثاني؟","شو بصير بالرسوم اذا انسحبت من الموازي بعد الأسبوع الثالث؟"),
])

S('0209',"قرارات مالية متفرقة / الرسوم الدراسية لجميع الطلبة / أبناء الشهداء",[
("rule",[1],"القرار 1 و2","يتمتع أبناء الشهداء والمتوفين والمصابين بعاهات جسيمة تمنعهم من إعالة أنفسهم بسبب من العمليات الحربية بالمجانية الكاملة في جميع مراحل التعليم بمدارس ومعاهد وزارة التربية والتعليم أو الجامعات أو الكليات أو بالمدارس العسكرية الأردنية بجميع درجاتها العلمية، على ألا يتجاوز عمر المستفيد عن خمسة وثلاثين عاماً، وذلك إذا ما استوفوا شروط القبول بتلك المدارس والمعاهد والكليات والجامعات.",
 "هل يعفى أبناء الشهداء من الرسوم الجامعية؟","ما العمر الأقصى للاستفادة من مجانية التعليم لأبناء الشهداء؟","ابن الشهيد بدفع رسوم جامعية؟"),
])

S('0210',"قرارات مالية متفرقة / الرسوم الدراسية لجميع الطلبة / ذوو الاحتياجات الخاصة",[
("number",[1],"الرسوم الجامعية / التوصية","تحدد الرسوم الجامعية للطلبة المعوقين الذين تبلغ نسبة إعاقتهم الوظيفية (40%) فأكثر بما نسبته (10%) من رسوم الساعات المعتمدة في الجامعات الأردنية الرسمية لدرجة البكالوريوس، وللدراسات العليا بما نسبته (90%) من رسوم الساعات المعتمدة في الجامعات الأردنية الرسمية. وتكون المرجعية للتقارير الطبية هي المجلس الأعلى لشؤون الأشخاص المعوقين.",
 "كم نسبة رسوم الساعات المعتمدة لطلبة البكالوريوس المعوقين الذين تبلغ إعاقتهم الوظيفية 40% فأكثر؟","ما الجهة المرجعية للتقارير الطبية للطلبة المعوقين؟","كم بدفع رسوم ساعات اذا عندي إعاقة 40% أو أكتر؟"),
("number",[1],"إعفاء","يعفى المعوقون من طلبة الجامعات الأردنية من حد أقصى لا يتجاوز (90%) من قيمة الرسوم الدراسية (الساعات المعتمدة) إذا ثبتت عدم قدرتهم على الدفع، أما الرسوم الأخرى فيدفعونها كاملة. والضعف في الإبصار وحدة الإبصار والكسل البصري لا يعطوا أي نسبة خصم على الرسوم الدراسية حتى لو كان معهم نسبة عجز ومعتمدة من الجهات المختصة.",
 "هل يعفى ذوو الإعاقة من الرسوم الأخرى غير رسوم الساعات؟","هل يعطى الطالب ضعيف البصر خصماً على الرسوم الدراسية؟","اذا عندي ضعف نظر بنزلولي رسوم الجامعة؟"),
("number",[1],"تجسير ذوي الاحتياجات الخاصة","الموافقة على قبول الطلبة الأردنيين ذوي الاحتياجات الخاصة تجسيراً إلى الجامعات الأردنية الرسمية والخاصة، باستثناء شرط ربط معدل امتحان الشامل (بحد أدنى 65%) مع معدل شهادة الثانوية العامة، شريطة إحضار وثيقة طبية صادرة عن مركز تشخيص الإعاقات التابعة لوزارة الصحة على ألا تقل نسبة الإعاقة عن (30%).",
 "ما الحد الأدنى لنسبة الإعاقة لقبول ذوي الاحتياجات الخاصة تجسيراً؟","ما الوثيقة المطلوبة لقبول ذوي الاحتياجات الخاصة تجسيراً؟","بقبلوني تجسير اذا عندي إعاقة؟"),
("rule",[1],"قرار 1988","الإعفاء الوارد في قرار مجلس التعليم العالي رقم (224) تاريخ 14/3/1988 لطلبة البكالوريوس المعاقين يشمل فقط البرنامج العادي (الصباحي).",
 "هل يشمل إعفاء المعاقين برنامج الموازي؟","أي برنامج يشمله إعفاء طلبة البكالوريوس المعاقين؟","الإعفاء للمعاقين بيشمل الموازي؟"),
])

S('0211',"تعليمات تعديل البيانات الشخصية للطالب (اسم الطالب / الجنسية)",[
("rule",[1],"المادة 1 و2","تسمى هذه التعليمات «تعليمات تعديل البيانات الشخصية للطالب (اسم الطالب / الجنسية) في كافة الوثائق والشهادات التي تصدرها جامعة العلوم والتكنولوجيا الأردنية»، ويعمل بها اعتباراً من تاريخ إقرارها. ويقصد بـ«النموذج المعتمد» طلب تعديل البيانات الشخصية المعتمد في إجراءات وحدة القبول والتسجيل.",
 "ما التعليمات التي تنظم تعديل اسم الطالب وجنسيته في وثائق الجامعة؟","ما المقصود بالنموذج المعتمد في تعليمات تعديل البيانات الشخصية؟","شو التعليمات اللي بتخص تعديل الاسم والجنسية؟"),
("procedure",[1],"المادة 3","الوثائق اللازمة للتعديل للطالب الأردني: صورة مصدقة عن قرار التعديل الصادر عن المحكمة أو دائرة الأحوال المدنية، وصورة مصدقة عن هوية الأحوال المدنية حسب قرار التعديل، وصورة مصدقة عن وثائق مرحلة البكالوريوس لطالب الدراسات العليا، وموافقة الجهة الباعثة للطالب الملتحق في الجامعة، والنسخة الأصلية لوثائق التخرج حسب البيانات القديمة.",
 "ما الوثائق اللازمة لتعديل اسم الطالب الأردني في سجلات الجامعة؟","هل أحتاج النسخة الأصلية لوثائق التخرج لتعديل بياناتي؟","شو الأوراق اللي بدي أقدمها لتعديل اسمي؟"),
("rule",[1],"المادة 4","يتم تعديل بيانات الطالب بعد تعبئة النموذج المعتمد مع إرفاق الوثائق اللازمة بالتعديل الجديد ودفع رسوم تعديل البيانات الشخصية في وحدة الشؤون المالية. ويتم اعتماد اسم الطالب الأردني وباللغتين العربية والإنجليزية حسب كشف علامات الثانوية العامة الأردنية لحامله، ويتم اعتماد اسم الطالب حامل الثانوية غير الأردنية وباللغتين حسب بطاقة الأحوال المدنية الأردنية.",
 "كيف يعتمد اسم الطالب الأردني باللغتين العربية والإنجليزية؟","أين تدفع رسوم تعديل البيانات الشخصية؟","من وين بتنعتمد صيغة اسمي بالجامعة؟"),
("rule",[1],"المادة 5 و6","إذا حصل الطالب على الجنسية أثناء دراسته في الجامعة يتم التعديل حسب الجنسية الجديدة بعد التخرج على أن يحضر الطالب ما يثبت أنه حصل على الجنسية بعد قبوله في الجامعة، ولا يجوز تعديل الجنسية إلى أي جنسية أخرى. وتعد وثائق التخرج القديمة (قبل التصحيح) وثائق ملغاة ويعد استعمالها أو إساءة استعمال صورة عنها بعد استلام وثائق التخرج الجديدة جريمة تستوجب المسؤولية وفق القوانين المعمول بها في المملكة الأردنية الهاشمية.",
 "متى يعدل اسم الجنسية للطالب الذي حصل على الجنسية أثناء دراسته؟","ما مصير وثائق التخرج القديمة بعد تعديل البيانات؟","اذا غيرت جنسيتي، بتتعدل بالجامعة؟"),
("rule",[1],"المادة 7","يبت رئيس الجامعة في الإشكالات الناجمة عن تطبيق هذه التعليمات.",
 "من يبت في الإشكالات الناجمة عن تطبيق تعليمات تعديل البيانات الشخصية؟","من الجهة التي تحسم الإشكالات في تعديل البيانات الشخصية؟","مين بحل المشاكل اللي بتصير بتعديل الاسم؟"),
])
